Lemma rst0_region rid r : (s_regions st0) !! rid = Some r ->
  0 <= r_base r /\ r_base r + round_up_pg (r_len r) <= alloc_ceiling
  /\ (r_base r + round_up_pg (r_len r) <= 0x10000 \/ 0x34000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x34000 \/ 0xb4000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0xb4000 \/ 0xba000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0xba000 \/ 0xee000 <= r_base r).
